using NUnit.Framework;using Touchline.Core;using System.Linq;using System.Reflection;
namespace Touchline.Tests {public class CloseMarkTests {
Actor A(int side,int slot,float x,float z)=>new Actor{side=side,slot=slot,position=new Point(x,z)};
[TestCase(1)][TestCase(-1)]public void KeepsCloseUncoveredCentralRunner(int dir){var d=A(0,2,-48*dir,0);var s=A(1,9,-46.8f*dir,.5f);var wing=A(1,8,-47*dir,8);var m=A(0,4,-48*dir,8);Assert.AreSame(s,MatchSimulation.CloseGoalSideMark(d,wing,new[]{d,s,wing,m},dir));}
[Test]public void AllowsActualGoalSideHandoff(){var d=A(0,2,-48,2);var s=A(1,9,-47,0);var m=A(0,3,-47.6f,0);var wing=A(1,8,-47,8);Assert.AreSame(wing,MatchSimulation.CloseGoalSideMark(d,wing,new[]{d,s,m,wing},1));}
[Test]public void ChasingTeammateIsNotAGoalSideHandoff(){var d=A(0,2,-48,2);var s=A(1,9,-47,0);var m=A(0,3,-46,0);var wing=A(1,8,-47,8);Assert.AreSame(s,MatchSimulation.CloseGoalSideMark(d,wing,new[]{d,s,m,wing},1));}
[Test]public void DoesNotChangeMidfieldZone(){var d=A(0,2,-28,0);var s=A(1,9,-27,.5f);var wing=A(1,8,-27,8);Assert.AreSame(wing,MatchSimulation.CloseGoalSideMark(d,wing,new[]{d,s,wing},1));}
[Test]public void DoesNotAbandonTrackedRunnerWhoGetsAhead(){var d=A(0,2,-48,0);var s=A(1,9,-50,.5f);var wing=A(1,8,-47,8);Assert.AreSame(s,MatchSimulation.CloseGoalSideMark(d,wing,new[]{d,s,wing},1));}
[Test]public void DistantStrikerDoesNotOverrideZonalThreat(){var d=A(0,2,-48,0);var s=A(1,9,-43,.5f);var wing=A(1,8,-47,8);Assert.AreSame(wing,MatchSimulation.CloseGoalSideMark(d,wing,new[]{d,s,wing},1));}
[Test]public void KeeperAndSentOffOpponentCannotTakeMark(){var d=A(0,2,-48,0);var s=A(1,9,-47,.5f);s.sentOff=true;var g=A(1,0,-47,0);var wing=A(1,8,-47,8);Assert.AreSame(wing,MatchSimulation.CloseGoalSideMark(d,wing,new[]{d,s,g,wing},1));}
[TestCase("fall")][TestCase("slide")][TestCase("hurt")]public void IncapacitatedTeammateCannotTakeOverUntilActionEnds(string action){var d=A(0,2,-48,2);var s=A(1,9,-47,0);var m=A(0,3,-47.6f,0);m.action=action;m.actionTime=.4f;var wing=A(1,8,-47,8);Assert.AreSame(s,MatchSimulation.CloseGoalSideMark(d,wing,new[]{d,s,m,wing},1));m.actionTime=0;Assert.AreSame(wing,MatchSimulation.CloseGoalSideMark(d,wing,new[]{d,s,m,wing},1));}
[TestCase("fall")][TestCase("slide")][TestCase("hurt")]public void IncapacitatedThreatIsNotPrioritizedUntilActionEnds(string action){var d=A(0,2,-48,0);var s=A(1,9,-47,.5f);s.action=action;s.actionTime=.4f;var wing=A(1,8,-47,8);Assert.AreSame(wing,MatchSimulation.CloseGoalSideMark(d,wing,new[]{d,s,wing},1));s.actionTime=0;Assert.AreSame(s,MatchSimulation.CloseGoalSideMark(d,wing,new[]{d,s,wing},1));}
[TestCase(1)][TestCase(2)]public void MovingCutbackDoesNotPullCentralDefenderOntoAlreadyCoveredWinger(int period){
 var db=new Database{players=Enumerable.Range(0,40).Select(i=>new PlayerData{id="close"+i,name="P"+i,team=i<20?"a":"b",position=i%20==0?"GB":i%20<5?"DEF":i%20<9?"MIL":"ATT",rating=75}).ToArray()};var career=new Career{club="a"};career.lineup=Career.Select(db,"a",career.tactic);var sim=MatchSimulation.Create(db,career,"b",731,2700);var m=sim.State;m.period=period;m.clock=531.4f;m.restart=0;m.turnoverAt=522;m.possessionSide=0;m.awayTactic.SetFormation("4-4-2");m.awayTactic.line=.2f;m.awayTactic.pressing=.2756f;m.awayTactic.directness=.717f;
 var points=new[]{new Point(-46.965f,-1.148f),new Point(47.860f,25.329f),new Point(-1.087f,7.312f),new Point(-1.087f,-12.206f),new Point(47.775f,-30.007f),new Point(39.929f,-.373f),new Point(17.812f,-2.447f),new Point(47.000f,-24.089f),new Point(46.515f,6.034f),new Point(48.262f,-3.229f),new Point(48.121f,-30.648f),new Point(51.497f,-2.891f),new Point(49.609f,-24.574f),new Point(50.420f,-19.047f),new Point(48.956f,-1.867f),new Point(48.576f,8.540f),new Point(46.594f,-25.588f),new Point(45.722f,-22.930f),new Point(47.709f,.181f),new Point(47.159f,9.993f),new Point(10.445f,-14.792f),new Point(10.455f,.179f)};int mirror=period==1?1:-1;for(int i=0;i<22;i++)m.actors[i].position=m.actors[i].previous=points[i]*mirror;
 m.ball=new BallState{kind="cutback",side=0,from=m.actors[7].id,to=m.actors[5].id,position=new Point(43.603f,-13.840f)*mirror,previous=new Point(44.231f,-15.734f)*mirror,start=new Point(46.868f,-23.691f)*mirror,end=new Point(38.880f,.407f)*mirror,elapsed=.52f,duration=1.272f,height=.187f,startHeight=.11f,endHeight=.11f,loft=.08f};
 typeof(MatchSimulation).GetMethod("Move",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(sim,null);Assert.AreEqual("mark",m.actors[14].intent);Assert.Less(sim.MovementTarget(14).z*mirror,0,"Torrente's waypoint must stay with the central runner instead of switching to the winger already covered by the right back.");
}
}}
